prompt --application/shared_components/user_interface/templates/list/dock_bar
begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(857241267533120609)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TDockBar #COMPONENT_CSS_CLASSES#" id="#LIST_ID#">',
'<ul class="amc-TDockBar-shelf">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'</div>'))
,p_list_template_current=>'<li class="amc-TDockBar-item is-current"><a class="amc-TDockBar-link" href="#LINK#" aria-current="page"><span class="amc-TDockBar-tip"><span class="amc-TDockBar-label">#TEXT#</span></span><span class="amc-TDockBar-tile"><span class="amc-TDockBar-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TDockBar-badge">#A01#</span></span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TDockBar-item"><a class="amc-TDockBar-link" href="#LINK#"><span class="amc-TDockBar-tip"><span class="amc-TDockBar-label">#TEXT#</span></span><span class="amc-TDockBar-tile"><span class="amc-TDockBar-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TDockBar-badge">#A01#</span></span></a></li>'
,p_list_template_name=>'AMC Dock Bar'
,p_internal_name=>'AMC_TPL_DOCK_BAR'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-dock-bar.css'
,p_a01_label=>'Badge count'
,p_list_template_comment=>'List template for a List region. Each entry is an icon tile; the entry text is the tooltip label and User Defined Attribute 1 is an optional badge count shown in the danger color, for example 12. The tile under the pointer or with keyboard focus grows, and its two neighbours on each side grow less (pure CSS, no JavaScript). The current entry gets a glowing dot on the shelf. Neighbouring tiles rotate the theme''s primary hue in browsers with relative color syntax. On touch screens labels are always visible; in containers narrower than 420px the dock wraps into a glass tray with labels under the tiles. Reduced motion turns magnification into a focus ring. Template options: Large tiles, Always show labels, Soft tiles, Flat glass dock, Float at page bottom.'
);
end;
